@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* The header, then Split's narrow nav column (the design's 232 px
   settings menu, its items 4 apart) beside the page's cards, 24 apart. The usage meters sit two to a
   row once their card is 30rem wide (a container query on the main column). */
@layer nz.patterns {
  .nzp-plan-billing-page {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-6);
    min-inline-size: 0;
  }

  .nzp-plan-billing-page-nav {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .nzp-plan-billing-page-main {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-6);
    container-type: inline-size;
  }

  .nzp-plan-billing-page-plan {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-1);
  }

  .nzp-plan-billing-page-plan > p {
    margin: 0;
  }

  .nzp-plan-billing-page-usage {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--nz-space-5) var(--nz-space-6);
  }

  @container (width >= 30rem) {
    .nzp-plan-billing-page-usage {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  .nzp-plan-billing-page-method {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--nz-space-3);
  }

  .nzp-plan-billing-page-card-mark {
    flex: none;
    inline-size: 3rem;
    block-size: 2rem;
    border-radius: var(--nz-radius-sm);
    background: var(--nz-bg-muted);
  }

  /* The "View all" text link: Label/M in text/brand */
  .nzp-plan-billing-page-link {
    color: var(--nz-text-brand);
    font: var(--nz-font-label-m);
    letter-spacing: var(--nz-tracking-label-m);
  }

  .nzp-plan-billing-page-card-text {
    display: flex;
    flex: 1 1 10rem;
    flex-direction: column;
    gap: var(--nz-space-0-5);
  }
}
